import sys
# Ensure project root is on sys.path before importing any project modules
sys.path.insert(0, r'/home/carme/ATPA_CIF')

# Essential imports (guaranteed to be available)
import os
import torch
import torch.nn as nn
import torch.nn.functional as F
import torch.optim as optim
from data_loader import build_train_val_dataloaders
import json
from tqdm import tqdm
import numpy as np
from sklearn.metrics import roc_auc_score


# Configuration parameters
NUM_EPOCHS = 20
MAX_BATCH_SIZE = 32
LEARNING_RATE = 0.001
DROPOUT_RATE = 0.5
WEIGHT_DECAY = 1e-4
NUM_SPECIES = 206

# Data loading
DATA_DIR = "/mnt/disks/data/birdclef"
METADATA_FILE = os.path.join(DATA_DIR, "train.csv")
train_loader, val_loader = build_train_val_dataloaders(
    metadata_csv=METADATA_FILE,
    audio_dir=DATA_DIR,
    batch_size=MAX_BATCH_SIZE,
    augment=True,
    val_split=0.2,
)

# Model definition
class BirdCLEFModel(nn.Module):
    def __init__(self, num_species, dropout_rate=0.5):
        super(BirdCLEFModel, self).__init__()
        self.conv_layers = nn.Sequential(
            nn.Conv2d(1, 32, 3, padding=1), nn.BatchNorm2d(32), nn.ReLU(),
            nn.Conv2d(32, 64, 3, padding=1), nn.BatchNorm2d(64), nn.ReLU(),
            nn.Conv2d(64, 128, 3, padding=1), nn.BatchNorm2d(128), nn.ReLU(),
        )
        self.pool = nn.AdaptiveAvgPool2d((1, 1))
        self.classifier = nn.Sequential(
            nn.Linear(128, 128), nn.ReLU(), nn.Dropout(dropout_rate),
            nn.Linear(128, num_species)
        )

    def forward(self, x):
        x = self.conv_layers(x)
        x = self.pool(x).view(x.size(0), -1)
        return torch.sigmoid(self.classifier(x))

# Initialize model, loss function, and optimizer
model = BirdCLEFModel(NUM_SPECIES, dropout_rate=DROPOUT_RATE).to('cuda')
criterion = nn.BCELoss()
optimizer = optim.Adam(model.parameters(), lr=LEARNING_RATE, weight_decay=WEIGHT_DECAY)

# Training loop
best_auc = 0.0
early_stopping_patience = 5
no_improve_epochs = 0

for epoch in range(NUM_EPOCHS):
    model.train()
    train_loss = 0.0
    for batch_idx, (inputs, labels) in enumerate(train_loader):
        inputs, labels = inputs.to('cuda'), labels.to('cuda')
        
        try:
            optimizer.zero_grad()
            outputs = model(inputs)
            loss = criterion(outputs, labels.float())
            loss.backward()
            optimizer.step()
            
            train_loss += loss.item()
            torch.cuda.empty_cache()  # Prevent GPU fragmentation
            
        except RuntimeError as e:
            if 'out of memory' in str(e):
                print("OOM detected. Reducing batch size and retrying...")
                torch.cuda.empty_cache()
                MAX_BATCH_SIZE //= 2
                continue
        
        # Limit training to a subset for faster iteration
        if batch_idx >= 10:  # Limit to N batches for fast feedback
            break

    avg_train_loss = train_loss / (batch_idx + 1)
    print(f'Epoch [{epoch+1}/{NUM_EPOCHS}], Train Loss: {avg_train_loss:.4f}')
    
    # Validation
    model.eval()
    all_preds = []
    all_labels = []
    with torch.no_grad():
        for inputs, labels in val_loader:
            inputs, labels = inputs.to('cuda'), labels.to('cuda')
            outputs = model(inputs)
            all_preds.append(outputs.cpu().numpy())
            all_labels.append(labels.cpu().numpy())

    all_preds = np.vstack(all_preds)
    all_labels = np.vstack(all_labels)
    
    try:
        auc = roc_auc_score(all_labels, all_preds, average='weighted')
        print(f'Epoch [{epoch+1}/{NUM_EPOCHS}], Validation AUC: {auc:.4f}')
        
        if auc > best_auc:
            best_auc = auc
            no_improve_epochs = 0
            torch.save(model.state_dict(), 'model.pt')  # Save the best model
        else:
            no_improve_epochs += 1
            if no_improve_epochs >= early_stopping_patience:
                print("Early stopping triggered.")
                break

    except ValueError as e:
        print(f"Error calculating AUC: {e}")
        auc = np.nan

# Save metrics to JSON
metrics = {
    "final_train_loss": avg_train_loss,
    "final_auc": best_auc if not np.isnan(best_auc) else 0.0,
    "num_params": sum(p.numel() for p in model.parameters()),
    "epochs_trained": epoch + 1,
    "batch_size": MAX_BATCH_SIZE,
    "training_samples": len(train_loader.dataset),
    "eval_samples": len(val_loader.dataset)
}

with open('metrics.json', 'w') as f:
    json.dump(metrics, f)

print("METRICS: " + json.dumps(metrics))